"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { auth } from "@/lib/auth";
import { db } from "@/lib/db";
import { z } from "zod";

const registerSchema = z.object({
  // Sahip bilgileri
  ownerFirstName: z.string().min(1, "Ad zorunludur"),
  ownerLastName: z.string().min(1, "Soyad zorunludur"),
  ownerPhone: z.string().min(10, "Geçerli telefon numarası girin"),
  ownerEmail: z.string().email().optional().or(z.literal("")),
  ownerTcNo: z.string().optional(),
  ownerCity: z.string().optional(),
  ownerDistrict: z.string().optional(),
  ownerNotes: z.string().optional(),
  kvkkConsent: z.coerce.boolean(),

  // Hayvan bilgileri
  petName: z.string().min(1, "Hayvan adı zorunludur"),
  petSpecies: z.enum(["DOG", "CAT", "BIRD", "RABBIT", "REPTILE", "RODENT", "OTHER"]),
  petBreed: z.string().optional(),
  petGender: z.enum(["MALE", "FEMALE", "UNKNOWN"]).default("UNKNOWN"),
  petBirthDate: z.string().optional(),
  petColor: z.string().optional(),
  petMicrochip: z.string().optional(),
  petIsNeutered: z.coerce.boolean().default(false),
  petNotes: z.string().optional(),
});

export type RegisterFormState = {
  success?: boolean;
  petId?: string;
  errors?: Record<string, string[]>;
  message?: string;
};

export async function registerPetWithOwner(
  prevState: RegisterFormState,
  formData: FormData
): Promise<RegisterFormState> {
  const session = await auth();
  if (!session) return { message: "Oturum bulunamadı" };

  const raw = Object.fromEntries(formData.entries());
  const parsed = registerSchema.safeParse({
    ...raw,
    kvkkConsent: raw.kvkkConsent === "on" || raw.kvkkConsent === "true",
    petIsNeutered: raw.petIsNeutered === "on" || raw.petIsNeutered === "true",
  });

  if (!parsed.success) {
    return { errors: parsed.error.flatten().fieldErrors as Record<string, string[]> };
  }

  const d = parsed.data;

  try {
    // Transaction: önce sahip, sonra hayvan
    const result = await db.$transaction(async (tx: any) => {
      const owner = await tx.petOwner.create({
        data: {
          tenantId: session.user.tenantId,
          firstName: d.ownerFirstName,
          lastName: d.ownerLastName,
          phone: d.ownerPhone,
          email: d.ownerEmail || null,
          tcNo: d.ownerTcNo || null,
          address: {
            city: d.ownerCity || "",
            district: d.ownerDistrict || "",
          },
          notes: d.ownerNotes || null,
          kvkkConsent: d.kvkkConsent,
          kvkkDate: d.kvkkConsent ? new Date() : null,
        },
      });

      const pet = await tx.pet.create({
        data: {
          tenantId: session.user.tenantId,
          ownerId: owner.id,
          name: d.petName,
          species: d.petSpecies,
          breed: d.petBreed || null,
          gender: d.petGender,
          birthDate: d.petBirthDate ? new Date(d.petBirthDate) : null,
          color: d.petColor || null,
          microchip: d.petMicrochip || null,
          isNeutered: d.petIsNeutered,
          notes: d.petNotes || null,
        },
      });

      return { owner, pet };
    });

    revalidatePath("/dashboard/patients");
    return { success: true, petId: result.pet.id };
  } catch (error) {
    console.error("[registerPetWithOwner]", error);
    return { message: "Kayıt sırasında bir hata oluştu. Lütfen tekrar deneyin." };
  }
}

export async function addPetToExistingOwner(
  ownerId: string,
  formData: FormData
): Promise<{ success: boolean; petId?: string; error?: string }> {
  const session = await auth();
  if (!session) return { success: false, error: "Oturum bulunamadı" };

  try {
    const pet = await db.pet.create({
      data: {
        tenantId: session.user.tenantId,
        ownerId,
        name: formData.get("petName") as string,
        species: formData.get("petSpecies") as never,
        breed: (formData.get("petBreed") as string) || null,
        gender: (formData.get("petGender") as never) || "UNKNOWN",
        birthDate: formData.get("petBirthDate")
          ? new Date(formData.get("petBirthDate") as string)
          : null,
        microchip: (formData.get("petMicrochip") as string) || null,
        isNeutered: formData.get("petIsNeutered") === "on",
      },
    });

    revalidatePath(`/dashboard/patients/${pet.id}`);
    revalidatePath("/dashboard/patients");
    return { success: true, petId: pet.id };
  } catch (error) {
    console.error("[addPetToExistingOwner]", error);
    return { success: false, error: "Kayıt hatası" };
  }
}

import { auth } from "@/lib/auth";
import { handlers } from "@/lib/auth";

export const { GET, POST } = handlers;

import Link from "next/link";
import { auth } from "@/lib/auth";
import { db } from "@/lib/db";
import {
  Calendar, Plus, ChevronLeft, ChevronRight,
  Clock, User, Phone, CheckCircle2, XCircle,
  Activity, AlertCircle, Search, Filter,
} from "lucide-react";
import AppointmentStatusButton from "./AppointmentStatusButton";

const speciesIcon: Record<string, string> = {
  DOG: "🐕", CAT: "🐱", BIRD: "🐦", RABBIT: "🐇",
  REPTILE: "🦎", RODENT: "🐭", OTHER: "🐾",
};

const typeLabel: Record<string, { label: string; color: string }> = {
  CHECKUP: { label: "Kontrol", color: "bg-blue-500/10 text-blue-400 border-blue-500/20" },
  VACCINATION: { label: "Aşı", color: "bg-violet-500/10 text-violet-400 border-violet-500/20" },
  SURGERY: { label: "Ameliyat", color: "bg-red-500/10 text-red-400 border-red-500/20" },
  GROOMING: { label: "Tıraş", color: "bg-pink-500/10 text-pink-400 border-pink-500/20" },
  HOTEL: { label: "Otel", color: "bg-amber-500/10 text-amber-400 border-amber-500/20" },
  LAB: { label: "Laboratuvar", color: "bg-cyan-500/10 text-cyan-400 border-cyan-500/20" },
  EMERGENCY: { label: "Acil", color: "bg-red-500/10 text-red-300 border-red-500/30" },
  FOLLOWUP: { label: "Takip", color: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20" },
};

const statusConfig: Record<string, { label: string; cls: string; icon: string }> = {
  SCHEDULED: { label: "Planlandı", cls: "bg-slate-500/10 text-slate-400 border-slate-500/20", icon: "📅" },
  CONFIRMED: { label: "Onaylandı", cls: "bg-blue-500/10 text-blue-400 border-blue-500/20", icon: "✅" },
  IN_PROGRESS: { label: "Devam Ediyor", cls: "bg-amber-500/10 text-amber-400 border-amber-500/20", icon: "🔄" },
  COMPLETED: { label: "Tamamlandı", cls: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20", icon: "✓" },
  CANCELLED: { label: "İptal", cls: "bg-red-500/10 text-red-400 border-red-500/20", icon: "✗" },
  NO_SHOW: { label: "Gelmedi", cls: "bg-slate-500/10 text-slate-500 border-slate-500/20", icon: "?" },
};

function getWeekDates(dateStr: string) {
  const date = new Date(dateStr);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1);
  const monday = new Date(date.setDate(diff));
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    days.push(d);
  }
  return days;
}

const HOURS = Array.from({ length: 13 }, (_, i) => i + 8); // 08:00 - 20:00

async function getAppointments(tenantId: string, date: string) {
  const weekDates = getWeekDates(date);
  const weekStart = new Date(weekDates[0]);
  weekStart.setHours(0, 0, 0, 0);
  const weekEnd = new Date(weekDates[6]);
  weekEnd.setHours(23, 59, 59, 999);

  const [appointments, vets] = await Promise.all([
    db.appointment.findMany({
      where: {
        tenantId,
        startTime: { gte: weekStart, lte: weekEnd },
      },
      include: {
        pet: { select: { id: true, name: true, species: true, breed: true } },
        vet: { select: { id: true, firstName: true, lastName: true, title: true } },
      },
      orderBy: { startTime: "asc" },
    }),
    db.user.findMany({
      where: { tenantId, isActive: true, role: { in: ["VET", "ADMIN", "OWNER"] } },
      select: { id: true, firstName: true, lastName: true, title: true },
      orderBy: { firstName: "asc" },
    }),
  ]);

  return { appointments, vets, weekDates };
}

export default async function AppointmentsPage({
  searchParams,
}: {
  searchParams: Promise<{ date?: string; view?: string }>;
}) {
  const session = await auth();
  if (!session) return null;

  const { date: dateParam, view = "week" } = await searchParams;
  const today = new Date();
  const selectedDate = dateParam || today.toISOString().split("T")[0];
  const { appointments, vets, weekDates } = await getAppointments(session.user.tenantId, selectedDate);

  // Navigasyon tarihleri
  const prevWeek = new Date(weekDates[0]);
  prevWeek.setDate(prevWeek.getDate() - 7);
  const nextWeek = new Date(weekDates[0]);
  nextWeek.setDate(nextWeek.getDate() + 7);

  const dayNames = ["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"];
  const monthNames = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];

  // Bugünün randevuları (liste görünümü için)
  const todayDateStr = today.toISOString().split("T")[0];
  const todayAppointments = appointments.filter((a) => {
    const d = new Date(a.startTime).toISOString().split("T")[0];
    return d === selectedDate;
  });

  // Haftalık istatistikler
  const totalWeekly = appointments.length;
  const completedWeekly = appointments.filter((a) => a.status === "COMPLETED").length;
  const cancelledWeekly = appointments.filter((a) => a.status === "CANCELLED").length;
  const todayCount = appointments.filter((a) => {
    const d = new Date(a.startTime).toISOString().split("T")[0];
    return d === todayDateStr;
  }).length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">Randevular</h1>
          <p className="text-slate-400 text-sm mt-0.5">
            {monthNames[weekDates[0].getMonth()]} {weekDates[0].getDate()} – {weekDates[6].getDate()}, {weekDates[0].getFullYear()}
          </p>
        </div>
        <Link
          href="/dashboard/appointments/new"
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 text-white px-4 py-2.5 rounded-xl text-sm font-medium transition-all shadow-lg shadow-blue-600/20"
        >
          <Plus className="w-4 h-4" />
          Yeni Randevu
        </Link>
      </div>

      {/* Mini İstatistikler */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: "Bugün", value: todayCount, color: "blue" },
          { label: "Haftalık Toplam", value: totalWeekly, color: "violet" },
          { label: "Tamamlanan", value: completedWeekly, color: "emerald" },
          { label: "İptal Edilen", value: cancelledWeekly, color: "red" },
        ].map((stat) => (
          <div key={stat.label} className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-3.5">
            <div className={`text-xl font-bold ${
              stat.color === "blue" ? "text-blue-400" :
              stat.color === "violet" ? "text-violet-400" :
              stat.color === "emerald" ? "text-emerald-400" :
              "text-red-400"
            }`}>
              {stat.value}
            </div>
            <div className="text-xs text-slate-500 mt-0.5">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Takvim Navigasyonu */}
      <div className="bg-slate-900/60 border border-slate-800/60 rounded-2xl overflow-hidden">
        <div className="flex items-center justify-between px-5 py-3 border-b border-slate-800/60">
          <div className="flex items-center gap-2">
            <Link
              href={`/dashboard/appointments?date=${prevWeek.toISOString().split("T")[0]}`}
              className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition-all"
            >
              <ChevronLeft className="w-4 h-4" />
            </Link>
            <Link
              href={`/dashboard/appointments?date=${todayDateStr}`}
              className="px-3 py-1 text-sm font-medium text-blue-400 hover:text-blue-300 bg-blue-500/10 rounded-lg transition-colors"
            >
              Bugün
            </Link>
            <Link
              href={`/dashboard/appointments?date=${nextWeek.toISOString().split("T")[0]}`}
              className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition-all"
            >
              <ChevronRight className="w-4 h-4" />
            </Link>
          </div>

          <div className="flex items-center gap-2">
            {vets.length > 0 && (
              <div className="hidden sm:flex items-center gap-1.5 text-xs text-slate-500">
                <User className="w-3.5 h-3.5" />
                {vets.length} veteriner
              </div>
            )}
          </div>
        </div>

        {/* Haftalık Takvim Görünümü */}
        <div className="overflow-x-auto">
          <div className="min-w-[700px]">
            {/* Gün başlıkları */}
            <div className="grid grid-cols-8 border-b border-slate-800/40">
              <div className="p-2 text-xs text-slate-600 text-center border-r border-slate-800/30">
                <Clock className="w-3.5 h-3.5 mx-auto" />
              </div>
              {weekDates.map((d, i) => {
                const isToday = d.toISOString().split("T")[0] === todayDateStr;
                const isSelected = d.toISOString().split("T")[0] === selectedDate;
                const dayAppointments = appointments.filter(
                  (a) => new Date(a.startTime).toISOString().split("T")[0] === d.toISOString().split("T")[0]
                );
                return (
                  <Link
                    key={i}
                    href={`/dashboard/appointments?date=${d.toISOString().split("T")[0]}`}
                    className={`p-2.5 text-center border-r border-slate-800/30 last:border-r-0 transition-all hover:bg-slate-800/30 ${
                      isSelected ? "bg-blue-500/5" : ""
                    }`}
                  >
                    <div className="text-xs text-slate-500 font-medium">{dayNames[i]}</div>
                    <div className={`text-lg font-bold mt-0.5 ${
                      isToday ? "text-blue-400" : isSelected ? "text-white" : "text-slate-300"
                    }`}>
                      {d.getDate()}
                    </div>
                    {dayAppointments.length > 0 && (
                      <div className="flex items-center justify-center gap-0.5 mt-1">
                        <div className={`w-1.5 h-1.5 rounded-full ${isToday ? "bg-blue-400" : "bg-slate-500"}`} />
                        <span className="text-[10px] text-slate-500">{dayAppointments.length}</span>
                      </div>
                    )}
                  </Link>
                );
              })}
            </div>

            {/* Zaman ızgarası */}
            {HOURS.map((hour) => {
              return (
                <div key={hour} className="grid grid-cols-8 border-b border-slate-800/20 min-h-[52px]">
                  <div className="p-1.5 text-xs text-slate-600 font-mono text-center border-r border-slate-800/30 flex items-start justify-center pt-2">
                    {hour.toString().padStart(2, "0")}:00
                  </div>
                  {weekDates.map((d, dayIdx) => {
                    const dayStr = d.toISOString().split("T")[0];
                    const hourAppointments = appointments.filter((a) => {
                      const aDate = new Date(a.startTime);
                      return aDate.toISOString().split("T")[0] === dayStr && aDate.getHours() === hour;
                    });

                    return (
                      <div
                        key={dayIdx}
                        className="border-r border-slate-800/30 last:border-r-0 p-0.5 relative"
                      >
                        {hourAppointments.map((appt) => {
                          const t = typeLabel[appt.type] || typeLabel.CHECKUP;
                          const time = new Date(appt.startTime);
                          return (
                            <Link
                              key={appt.id}
                              href={`/dashboard/patients/${appt.pet.id}`}
                              className={`block p-1.5 rounded-lg text-[10px] leading-tight mb-0.5 border transition-all hover:scale-[1.02] cursor-pointer ${t.color}`}
                            >
                              <div className="font-semibold truncate">
                                {time.toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })} {speciesIcon[appt.pet.species]} {appt.pet.name}
                              </div>
                              <div className="truncate opacity-70 mt-0.5">
                                {appt.vet.title || "Dr."} {appt.vet.lastName} · {t.label}
                              </div>
                            </Link>
                          );
                        })}
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Seçili Günün Randevu Listesi */}
      <div className="bg-slate-900/60 border border-slate-800/60 rounded-2xl">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-800/60">
          <h2 className="font-semibold text-white flex items-center gap-2">
            <Calendar className="w-4 h-4 text-blue-400" />
            {new Date(selectedDate).toLocaleDateString("tr-TR", { weekday: "long", day: "numeric", month: "long" })} Randevuları
          </h2>
          <span className="text-xs text-slate-500">{todayAppointments.length} randevu</span>
        </div>

        {todayAppointments.length === 0 ? (
          <div className="px-6 py-12 text-center">
            <div className="w-14 h-14 bg-slate-800/60 rounded-2xl flex items-center justify-center mx-auto mb-3">
              <Calendar className="w-7 h-7 text-slate-600" />
            </div>
            <p className="text-slate-400 font-medium">Bu tarihte randevu yok</p>
            <p className="text-slate-500 text-sm mt-1">Yeni randevu oluşturmak için butona tıklayın</p>
            <Link
              href="/dashboard/appointments/new"
              className="inline-flex items-center gap-2 mt-4 bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-xl text-sm font-medium transition-all"
            >
              <Plus className="w-4 h-4" />
              Randevu Oluştur
            </Link>
          </div>
        ) : (
          <div className="divide-y divide-slate-800/40">
            {todayAppointments.map((appt) => {
              const type = typeLabel[appt.type] || typeLabel.CHECKUP;
              const status = statusConfig[appt.status] || statusConfig.SCHEDULED;
              return (
                <div
                  key={appt.id}
                  className="px-6 py-4 flex items-center gap-4 hover:bg-slate-800/20 transition-colors group"
                >
                  {/* Saat */}
                  <div className="flex-shrink-0 w-16 text-center">
                    <div className="text-sm font-mono font-semibold text-white">
                      {new Date(appt.startTime).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}
                    </div>
                    <div className="text-xs text-slate-500">{appt.duration} dk</div>
                  </div>

                  {/* Hayvan */}
                  <div className="text-2xl">{speciesIcon[appt.pet.species]}</div>
                  <div className="flex-1 min-w-0">
                    <Link
                      href={`/dashboard/patients/${appt.pet.id}`}
                      className="text-sm font-medium text-white hover:text-blue-400 transition-colors"
                    >
                      {appt.pet.name}
                    </Link>
                    {appt.pet.breed && (
                      <span className="text-xs text-slate-500 ml-1.5">({appt.pet.breed})</span>
                    )}
                    {appt.reason && (
                      <div className="text-xs text-slate-500 mt-0.5 truncate">{appt.reason}</div>
                    )}
                  </div>

                  {/* Hekim */}
                  <div className="hidden sm:block text-right">
                    <div className="text-xs text-slate-400">
                      {appt.vet.title || "Dr."} {appt.vet.firstName} {appt.vet.lastName}
                    </div>
                  </div>

                  {/* Tür Badge */}
                  <span className={`text-xs px-2.5 py-1 rounded-full border font-medium hidden md:inline-flex ${type.color}`}>
                    {type.label}
                  </span>

                  {/* Status Badge */}
                  <span className={`text-xs px-2.5 py-1 rounded-full border font-medium ${status.cls}`}>
                    {status.icon} {status.label}
                  </span>

                  {/* Durum değiştirme*/}
                  <AppointmentStatusButton appointmentId={appt.id} currentStatus={appt.status} />
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import { auth } from "@/lib/auth";
import { db } from "@/lib/db";
import { notFound } from "next/navigation";
import Link from "next/link";
import {
  ArrowLeft, Calendar, User, Activity,
  Scale, Thermometer, Heart, Wind,
  FileText, Stethoscope, Clock,
  PawPrint,
} from "lucide-react";
import ExaminationSOAPForm from "./ExaminationSOAPForm";

const speciesIcon: Record<string, string> = {
  DOG: "🐕", CAT: "🐱", BIRD: "🐦", RABBIT: "🐇",
  REPTILE: "🦎", RODENT: "🐭", OTHER: "🐾",
};

const genderLabel: Record<string, string> = {
  MALE: "Erkek", FEMALE: "Dişi", UNKNOWN: "Bilinmiyor",
};

export default async function ExaminationDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const session = await auth();
  if (!session) return null;

  const { id } = await params;

  const examination = await db.examination.findFirst({
    where: { id, tenantId: session.user.tenantId },
    include: {
      pet: {
        select: {
          id: true, name: true, species: true, breed: true,
          gender: true, birthDate: true, color: true, microchip: true,
          isNeutered: true,
          owner: { select: { id: true, firstName: true, lastName: true, phone: true } },
        },
      },
      vet: {
        select: { id: true, firstName: true, lastName: true, title: true, diplomaNo: true },
      },
      appointment: {
        select: { id: true, type: true, status: true, startTime: true, reason: true },
      },
      prescription: {
        select: {
          id: true, status: true, issueDate: true,
          items: { select: { drugName: true, dosage: true } },
        },
      },
      files: true,
    },
  });

  if (!examination) notFound();

  const pet = examination.pet;
  const vet = examination.vet;
  const isSigned = examination.status === "SIGNED";

  // Pet yaş hesaplama
  let ageText = "";
  if (pet.birthDate) {
    const now = new Date();
    const birth = new Date(pet.birthDate);
    const months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
    if (months >= 12) {
      const years = Math.floor(months / 12);
      const remainingMonths = months % 12;
      ageText = `${years} yıl${remainingMonths > 0 ? ` ${remainingMonths} ay` : ""}`;
    } else {
      ageText = `${months} ay`;
    }
  }

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Link
            href="/dashboard/examinations"
            className="w-9 h-9 flex items-center justify-center rounded-xl text-slate-400 hover:text-white hover:bg-slate-800/60 transition-all"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
              <Stethoscope className="w-6 h-6 text-blue-400" />
              Muayene Detayı
            </h1>
            <p className="text-slate-400 text-sm mt-0.5">
              {new Date(examination.examDate).toLocaleString("tr-TR")} · #{examination.id.slice(-6)}
            </p>
          </div>
        </div>

        {/* Status badge */}
        <div className={`flex items-center gap-2 px-4 py-2 rounded-xl border text-sm font-medium ${
          isSigned
            ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
            : "bg-amber-500/10 text-amber-400 border-amber-500/20"
        }`}>
          {isSigned ? "✅ İmzalandı" : "📝 Taslak"}
          {isSigned && examination.signedAt && (
            <span className="text-xs opacity-60">
              · {new Date(examination.signedAt).toLocaleString("tr-TR")}
            </span>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sol Kolon — Hasta Bilgileri + Vital + Bağlantılar */}
        <div className="space-y-4">
          {/* Hasta Kartı */}
          <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-5">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-slate-800/80 rounded-xl flex items-center justify-center text-2xl">
                {speciesIcon[pet.species]}
              </div>
              <div>
                <Link
                  href={`/dashboard/patients/${pet.id}`}
                  className="text-lg font-bold text-white hover:text-blue-400 transition-colors"
                >
                  {pet.name}
                </Link>
                <div className="text-xs text-slate-500">
                  {pet.breed || "Irk belirtilmemiş"} · {genderLabel[pet.gender]}
                </div>
              </div>
            </div>

            <div className="space-y-2 text-xs">
              {ageText && (
                <div className="flex items-center gap-2 text-slate-400">
                  <Calendar className="w-3.5 h-3.5 text-slate-500" />
                  <span>{ageText}</span>
                </div>
              )}
              {pet.color && (
                <div className="flex items-center gap-2 text-slate-400">
                  <PawPrint className="w-3.5 h-3.5 text-slate-500" />
                  <span>{pet.color}</span>
                </div>
              )}
              {pet.microchip && (
                <div className="flex items-center gap-2 text-slate-400">
                  <Activity className="w-3.5 h-3.5 text-slate-500" />
                  <span>Çip: {pet.microchip}</span>
                </div>
              )}
              {pet.isNeutered && (
                <div className="text-slate-500">✓ Kısırlaştırılmış</div>
              )}
            </div>

            {/* Sahip bilgisi */}
            <div className="mt-4 pt-3 border-t border-slate-800/40">
              <div className="text-xs text-slate-500 mb-1">Sahip</div>
              <div className="text-sm text-slate-300">{pet.owner.firstName} {pet.owner.lastName}</div>
              {pet.owner.phone && (
                <div className="text-xs text-slate-500 mt-0.5">{pet.owner.phone}</div>
              )}
            </div>
          </div>

          {/* Vital Bulgular */}
          <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-5">
            <h3 className="text-sm font-medium text-slate-300 mb-3 flex items-center gap-2">
              <Activity className="w-4 h-4 text-emerald-400" />
              Vital Bulgular
            </h3>
            <div className="grid grid-cols-2 gap-3">
              {[
                { label: "Ağırlık", value: examination.weight, unit: "kg", icon: Scale, color: "blue" },
                { label: "Sıcaklık", value: examination.temperature, unit: "°C", icon: Thermometer, color: "red" },
                { label: "Kalp Atışı", value: examination.heartRate, unit: "bpm", icon: Heart, color: "pink" },
                { label: "Solunum", value: examination.respRate, unit: "/dk", icon: Wind, color: "cyan" },
                { label: "SpO₂", value: examination.spO2, unit: "%", icon: Activity, color: "emerald" },
              ].map((vital) => (
                <div key={vital.label} className="bg-slate-800/30 rounded-lg p-2.5">
                  <div className="flex items-center gap-1 mb-1">
                    <vital.icon className={`w-3 h-3 ${
                      vital.color === "blue" ? "text-blue-400" :
                      vital.color === "red" ? "text-red-400" :
                      vital.color === "pink" ? "text-pink-400" :
                      vital.color === "cyan" ? "text-cyan-400" :
                      "text-emerald-400"
                    }`} />
                    <span className="text-[10px] text-slate-500">{vital.label}</span>
                  </div>
                  <div className="text-sm font-semibold text-white">
                    {vital.value != null ? `${vital.value} ${vital.unit}` : (
                      <span className="text-slate-600 font-normal text-xs">—</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Veteriner */}
          <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-5">
            <h3 className="text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
              <User className="w-4 h-4 text-violet-400" />
              Muayene Eden
            </h3>
            <div className="text-sm text-white">{vet.title || "Dr."} {vet.firstName} {vet.lastName}</div>
            {vet.diplomaNo && <div className="text-xs text-slate-500 mt-0.5">Diploma: {vet.diplomaNo}</div>}
          </div>

          {/* Randevu Bağlantısı */}
          {examination.appointment && (
            <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-5">
              <h3 className="text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
                <Calendar className="w-4 h-4 text-blue-400" />
                Bağlı Randevu
              </h3>
              <div className="text-xs text-slate-400 space-y-1">
                <div>{new Date(examination.appointment.startTime).toLocaleString("tr-TR")}</div>
                <div>Tür: {examination.appointment.type}</div>
                {examination.appointment.reason && <div>Sebep: {examination.appointment.reason}</div>}
              </div>
            </div>
          )}

          {/* Reçeteler */}
          {examination.prescription.length > 0 && (
            <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-5">
              <h3 className="text-sm font-medium text-slate-300 mb-3 flex items-center gap-2">
                <FileText className="w-4 h-4 text-violet-400" />
                Reçeteler ({examination.prescription.length})
              </h3>
              <div className="space-y-2">
                {examination.prescription.map((rx) => (
                  <div key={rx.id} className="bg-slate-800/30 rounded-lg p-3">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-medium text-slate-300">
                        #{rx.id.slice(-6)}
                      </span>
                      <span className={`text-[10px] px-2 py-0.5 rounded-full border ${
                        rx.status === "ISSUED"
                          ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
                          : rx.status === "CANCELLED"
                          ? "bg-red-500/10 text-red-400 border-red-500/20"
                          : "bg-amber-500/10 text-amber-400 border-amber-500/20"
                      }`}>
                        {rx.status === "ISSUED" ? "Düzenlendi" : rx.status === "CANCELLED" ? "İptal" : "Taslak"}
                      </span>
                    </div>
                    {rx.items.map((item, i) => (
                      <div key={i} className="text-xs text-slate-500">
                        {item.drugName} — {item.dosage}
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Sağ Kolon — SOAP Düzenleme Formu */}
        <div className="lg:col-span-2">
          <ExaminationSOAPForm
            examination={{
              id: examination.id,
              subjective: examination.subjective,
              objective: examination.objective,
              assessment: examination.assessment,
              plan: examination.plan,
              diagnosisCodes: examination.diagnosisCodes,
              weight: examination.weight,
              temperature: examination.temperature,
              heartRate: examination.heartRate,
              respRate: examination.respRate,
              spO2: examination.spO2,
              status: examination.status,
            }}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useActionState, useState, useMemo } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  ArrowLeft, Search, Stethoscope, Thermometer,
  Heart, Wind, Activity, Scale, Save,
  Calendar, User, ChevronDown,
} from "lucide-react";
import { createExamination, type ExaminationFormState } from "@/app/actions/examinations";

const speciesIcon: Record<string, string> = {
  DOG: "🐕", CAT: "🐱", BIRD: "🐦", RABBIT: "🐇",
  REPTILE: "🦎", RODENT: "🐭", OTHER: "🐾",
};

type Pet = {
  id: string;
  name: string;
  species: string;
  breed: string | null;
  owner: { firstName: string; lastName: string };
};

type Vet = {
  id: string;
  firstName: string;
  lastName: string;
  title: string | null;
};

type Appointment = {
  id: string;
  type: string;
  reason: string | null;
  startTime: Date;
  pet: { id: string; name: string; species: string };
  vet: { id: string; firstName: string; lastName: string; title: string | null };
} | null;

export default function NewExaminationForm({
  pets,
  vets,
  appointment,
  preselectedPetId,
  preselectedVetId,
  currentVetId,
}: {
  pets: Pet[];
  vets: Vet[];
  appointment: Appointment;
  preselectedPetId?: string;
  preselectedVetId?: string;
  currentVetId: string;
}) {
  const router = useRouter();
  const [state, formAction, isPending] = useActionState<ExaminationFormState, FormData>(
    createExamination,
    {}
  );
  const [petSearch, setPetSearch] = useState("");
  const [selectedPetId, setSelectedPetId] = useState(preselectedPetId || "");
  const [selectedVetId, setSelectedVetId] = useState(preselectedVetId || currentVetId);
  const [showPetDropdown, setShowPetDropdown] = useState(false);
  const [activeSOAPTab, setActiveSOAPTab] = useState<"S" | "O" | "A" | "P">("S");

  const filteredPets = useMemo(() => {
    if (!petSearch) return pets.slice(0, 20);
    const q = petSearch.toLowerCase();
    return pets.filter(
      (p) =>
        p.name.toLowerCase().includes(q) ||
        p.owner.firstName.toLowerCase().includes(q) ||
        p.owner.lastName.toLowerCase().includes(q)
    ).slice(0, 20);
  }, [pets, petSearch]);

  const selectedPet = pets.find((p) => p.id === selectedPetId);

  // Redirect on success
  if (state.success && state.examinationId) {
    router.push(`/dashboard/examinations/${state.examinationId}`);
  }

  const soapTabs = [
    { key: "S" as const, label: "Subjective", desc: "Hasta sahibi şikayetleri", placeholder: "Hayvan sahibinin belirttiği şikayetler, semptomlar, süre, beslenme durumu..." },
    { key: "O" as const, label: "Objective", desc: "Fizik muayene bulguları", placeholder: "Fizik muayene bulguları, gözlemler, palpasyon sonuçları, genel durum..." },
    { key: "A" as const, label: "Assessment", desc: "Değerlendirme ve tanı", placeholder: "Ön tanı, ayırıcı tanı, teşhis kodları..." },
    { key: "P" as const, label: "Plan", desc: "Tedavi planı", placeholder: "Tedavi planı, ilaç önerileri, ameliyat planı, takip randevusu..." },
  ];

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Link
          href="/dashboard/examinations"
          className="w-9 h-9 flex items-center justify-center rounded-xl text-slate-400 hover:text-white hover:bg-slate-800/60 transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-white">Yeni Muayene</h1>
          <p className="text-slate-400 text-sm mt-0.5">
            {appointment ? `Randevu #${appointment.id.slice(-6)} üzerinden` : "Yeni muayene kaydı oluşturun"}
          </p>
        </div>
      </div>

      {/* Hata mesajı */}
      {state.message && (
        <div className="bg-red-500/10 border border-red-500/30 rounded-xl px-4 py-3 text-sm text-red-400">
          {state.message}
        </div>
      )}

      <form action={formAction} className="space-y-6">
        {appointment && (
          <input type="hidden" name="appointmentId" value={appointment.id} />
        )}
        <input type="hidden" name="petId" value={selectedPetId} />
        <input type="hidden" name="vetId" value={selectedVetId} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Sol Kolon — Hasta & Veteriner Seçimi + Vital */}
          <div className="space-y-4">
            {/* Randevu bilgisi */}
            {appointment && (
              <div className="bg-blue-500/5 border border-blue-500/20 rounded-xl p-4">
                <div className="flex items-center gap-2 text-blue-400 text-sm font-medium mb-2">
                  <Calendar className="w-4 h-4" />
                  Randevu Bilgisi
                </div>
                <div className="text-xs text-slate-400 space-y-1">
                  <div>{new Date(appointment.startTime).toLocaleString("tr-TR")}</div>
                  {appointment.reason && <div>Sebep: {appointment.reason}</div>}
                </div>
              </div>
            )}

            {/* Hasta Seçimi */}
            <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-4">
              <label className="text-sm font-medium text-slate-300 mb-2 block">Hasta *</label>
              {appointment ? (
                <div className="flex items-center gap-2 bg-slate-800/40 rounded-lg p-3">
                  <span className="text-lg">{speciesIcon[appointment.pet.species]}</span>
                  <span className="text-sm font-medium text-white">{appointment.pet.name}</span>
                </div>
              ) : (
                <div className="relative">
                  <div className="relative">
                    <input
                      type="text"
                      placeholder="Hasta ara..."
                      value={selectedPet ? `${speciesIcon[selectedPet.species]} ${selectedPet.name}` : petSearch}
                      onChange={(e) => {
                        setPetSearch(e.target.value);
                        setSelectedPetId("");
                        setShowPetDropdown(true);
                      }}
                      onFocus={() => setShowPetDropdown(true)}
                      className="w-full bg-slate-800/60 border border-slate-700/50 rounded-xl px-4 py-2.5 pl-10 text-sm text-slate-300 placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-blue-500/50 transition-all"
                    />
                    <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                  </div>
                  {showPetDropdown && !selectedPetId && (
                    <div className="absolute z-10 mt-1 w-full bg-slate-800 border border-slate-700/50 rounded-xl shadow-xl max-h-48 overflow-y-auto">
                      {filteredPets.map((pet) => (
                        <button
                          key={pet.id}
                          type="button"
                          onClick={() => {
                            setSelectedPetId(pet.id);
                            setPetSearch("");
                            setShowPetDropdown(false);
                          }}
                          className="w-full text-left px-4 py-2.5 hover:bg-slate-700/50 flex items-center gap-2 transition-colors text-sm"
                        >
                          <span>{speciesIcon[pet.species]}</span>
                          <div>
                            <div className="text-white font-medium">{pet.name}</div>
                            <div className="text-xs text-slate-500">{pet.owner.firstName} {pet.owner.lastName} · {pet.breed || ""}</div>
                          </div>
                        </button>
                      ))}
                      {filteredPets.length === 0 && (
                        <div className="px-4 py-3 text-xs text-slate-500">Sonuç bulunamadı</div>
                      )}
                    </div>
                  )}
                </div>
              )}
              {state.errors?.petId && (
                <p className="text-red-400 text-xs mt-1">{state.errors.petId[0]}</p>
              )}
            </div>

            {/* Veteriner Seçimi */}
            <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-4">
              <label className="text-sm font-medium text-slate-300 mb-2 block">Veteriner Hekim *</label>
              <div className="relative">
                <select
                  value={selectedVetId}
                  onChange={(e) => setSelectedVetId(e.target.value)}
                  className="w-full bg-slate-800/60 border border-slate-700/50 rounded-xl px-4 py-2.5 text-sm text-slate-300 focus:outline-none focus:ring-1 focus:ring-blue-500/50 appearance-none transition-all"
                >
                  <option value="">Hekim seçin</option>
                  {vets.map((v) => (
                    <option key={v.id} value={v.id}>
                      {v.title || "Dr."} {v.firstName} {v.lastName}
                    </option>
                  ))}
                </select>
                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 pointer-events-none" />
              </div>
            </div>

            {/* Vital Bulgular */}
            <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl p-4">
              <h3 className="text-sm font-medium text-slate-300 mb-3 flex items-center gap-2">
                <Activity className="w-4 h-4 text-emerald-400" />
                Vital Bulgular
              </h3>
              <div className="space-y-3">
                {[
                  { name: "weight", label: "Ağırlık", unit: "kg", icon: Scale, step: "0.1", placeholder: "Ör: 12.5" },
                  { name: "temperature", label: "Sıcaklık", unit: "°C", icon: Thermometer, step: "0.1", placeholder: "Ör: 38.5" },
                  { name: "heartRate", label: "Kalp Atışı", unit: "bpm", icon: Heart, step: "1", placeholder: "Ör: 120" },
                  { name: "respRate", label: "Solunum", unit: "/dk", icon: Wind, step: "1", placeholder: "Ör: 20" },
                  { name: "spO2", label: "SpO₂", unit: "%", icon: Activity, step: "0.1", placeholder: "Ör: 98" },
                ].map((vital) => (
                  <div key={vital.name} className="flex items-center gap-2">
                    <vital.icon className="w-3.5 h-3.5 text-slate-500 flex-shrink-0" />
                    <label className="text-xs text-slate-400 w-20 flex-shrink-0">{vital.label}</label>
                    <div className="flex-1 relative">
                      <input
                        type="number"
                        name={vital.name}
                        step={vital.step}
                        placeholder={vital.placeholder}
                        className="w-full bg-slate-800/40 border border-slate-700/40 rounded-lg px-3 py-1.5 text-sm text-slate-300 placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-blue-500/30 transition-all"
                      />
                      <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-600">{vital.unit}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Sağ Kolon — SOAP Formu */}
          <div className="lg:col-span-2">
            <div className="bg-slate-900/60 border border-slate-800/60 rounded-xl overflow-hidden">
              {/* SOAP Tabs */}
              <div className="flex border-b border-slate-800/60">
                {soapTabs.map((tab) => (
                  <button
                    key={tab.key}
                    type="button"
                    onClick={() => setActiveSOAPTab(tab.key)}
                    className={`flex-1 px-4 py-3 text-sm font-medium transition-all relative ${
                      activeSOAPTab === tab.key
                        ? "text-blue-400 bg-blue-500/5"
                        : "text-slate-500 hover:text-slate-300 hover:bg-slate-800/30"
                    }`}
                  >
                    <div className="flex items-center justify-center gap-2">
                      <span className={`w-6 h-6 rounded-lg flex items-center justify-center text-xs font-bold ${
                        activeSOAPTab === tab.key
                          ? "bg-blue-500/20 text-blue-400"
                          : "bg-slate-800 text-slate-500"
                      }`}>
                        {tab.key}
                      </span>
                      <span className="hidden sm:inline">{tab.label}</span>
                    </div>
                    {activeSOAPTab === tab.key && (
                      <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-500" />
                    )}
                  </button>
                ))}
              </div>

              {/* SOAP Content */}
              {soapTabs.map((tab) => (
                <div
                  key={tab.key}
                  className={activeSOAPTab === tab.key ? "block" : "hidden"}
                >
                  <div className="p-4">
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="text-sm font-medium text-slate-300">{tab.label}</h3>
                      <span className="text-xs text-slate-600">{tab.desc}</span>
                    </div>
                    <textarea
                      name={tab.key === "S" ? "subjective" : tab.key === "O" ? "objective" : tab.key === "A" ? "assessment" : "plan"}
                      rows={12}
                      placeholder={tab.placeholder}
                      className="w-full bg-slate-800/40 border border-slate-700/40 rounded-xl px-4 py-3 text-sm text-slate-300 placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-blue-500/30 resize-none transition-all leading-relaxed"
                    />
                  </div>
                </div>
              ))}

              {/* Teşhis Kodları */}
              <div className="border-t border-slate-800/60 p-4">
                <label className="text-sm font-medium text-slate-300 mb-2 block">Teşhis Kodları</label>
                <input
                  type="text"
                  name="diagnosisCodes"
                  placeholder="Ör: K29.0, J06.9 (virgülle ayırın)"
                  className="w-full bg-slate-800/40 border border-slate-700/40 rounded-xl px-4 py-2.5 text-sm text-slate-300 placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-blue-500/30 transition-all"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Submit */}
        <div className="flex items-center justify-end gap-3">
          <Link
            href="/dashboard/examinations"
            className="px-5 py-2.5 text-sm font-medium text-slate-400 hover:text-white transition-colors"
          >
            İptal
          </Link>
          <button
            type="submit"
            disabled={isPending || !selectedPetId || !selectedVetId}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 disabled:text-slate-500 text-white px-6 py-2.5 rounded-xl text-sm font-medium transition-all shadow-lg shadow-blue-600/20 disabled:shadow-none"
          >
            <Save className="w-4 h-4" />
            {isPending ? "Kaydediliyor..." : "Taslak Olarak Kaydet"}
          </button>
        </div>
      </form>
    </div>
  );
}

import Link from "next/link";
import { auth } from "@/lib/auth";
import { db } from "@/lib/db";
import {
  Stethoscope, Plus, FileText, CheckCircle2,
  Clock, User, Search, Filter, ArrowRight,
  Activity, ClipboardList, PenTool,
} from "lucide-react";

